<script setup lang="ts">
import { ref, computed } from 'vue';
import { Plus, Pencil, Save, X } from '@lucide/vue';
import type { Requirement, RequirementManifest } from '../../../shared/completeness';
import { requirementKindNames } from '../../../shared/completeness';
import { useTaskSection } from '../views/automation/use-task-section';
import { api, message } from '../api';
import { notify } from '../lib/notifications';
import TablePagination from './TablePagination.vue';
import Disclosure from './Disclosure.vue';
import BaseSelect from './BaseSelect.vue';
const props=defineProps<{taskId:string}>(),page=ref(1),edit=ref<Requirement>(),paths=ref(''),keys=ref(''),samples=ref(''),reason=ref(''),busy=ref(false),error=ref('');
const {data,loading,load,error:loadError}=useTaskSection<{manifest:Omit<RequirementManifest,'items'>|null;items:Requirement[];editable:boolean;page:number;pages:number;total:number}>(()=>`/automation/tasks/${props.taskId}/manifest/items?page=${page.value}&pageSize=20`);
const kinds=Object.entries(requirementKindNames).map(([value,label])=>({value,label}));
const visual=computed(()=>edit.value?.viewports.includes('desktop')||edit.value?.viewports.includes('mobile'));
function start(item?:Requirement){edit.value=item?structuredClone(item):{id:crypto.randomUUID(),title:'',kind:'page',required:true,source:'',expectation:'',paths:[],expectedCount:null,expectedKeys:[],viewports:['desktop','mobile']};paths.value=edit.value.paths.join('\n');keys.value=edit.value.expectedKeys?.join('\n')||'';samples.value=edit.value.samples?.join('\n')||'';reason.value='';error.value='';}
async function save(){if(!edit.value)return;busy.value=true;error.value='';try{await api(`/automation/tasks/${props.taskId}/manifest/items/${edit.value.id}`,{method:'PUT',body:JSON.stringify({expectedId:data.value?.manifest?.id||'',input:{...edit.value,paths:paths.value.split('\n').map(s=>s.trim()).filter(Boolean),expectedKeys:keys.value.split('\n').map(s=>s.trim()).filter(Boolean),samples:samples.value.split('\n').map(s=>s.trim()).filter(Boolean)},reason:reason.value||'人工调整交付清单'})});edit.value=undefined;await load();notify.success('已保存新的清单版本');}catch(e){error.value=message(e);}finally{busy.value=false;}}
</script>
<template><section v-if="data?.manifest||data?.editable" class="panel settings-panel"><div class="section-heading"><h2>全站交付清单</h2><button v-if="data.editable&&!edit" class="text-action" @click="start()"><Plus :size="15" />新增条目</button></div><p v-if="data.manifest" class="text-muted small-text">版本 {{data.manifest.revision}} · {{data.manifest.sourceComplete?'来源范围已确认':'来源范围尚有缺口'}}</p><Disclosure v-if="data.manifest?.limitations.length" label="来源覆盖与缺口"><ul class="task-text-list"><li v-for="s in data.manifest.limitations" :key="s">{{s}}</li></ul></Disclosure><p v-if="!data.manifest" class="text-muted">执行前由 AI 从冻结资料与来源站建立。也可在委托前手动添加条目。</p><p v-if="error" class="alert error">{{error}}</p>
  <form v-if="edit" class="manifest-editor" @submit.prevent="save"><div class="section-heading"><h3>编辑交付项</h3><button class="icon-button" type="button" aria-label="关闭编辑" @click="edit=undefined"><X :size="16" /></button></div><label class="field"><span>交付项名称</span><input v-model="edit.title" class="input" required /></label><div class="form-grid"><label class="field"><span>类型</span><BaseSelect v-model="edit.kind" :options="kinds" /></label><label class="field"><span>预期数量（未知留空）</span><input :value="edit.expectedCount??''" class="input" type="number" min="0" @input="edit.expectedCount=($event.target as HTMLInputElement).value===''?null:Number(($event.target as HTMLInputElement).value)" /></label></div><label class="field"><span>来源依据</span><textarea v-model="edit.source" class="input" rows="2" required /></label><label class="field"><span>完成要求</span><textarea v-model="edit.expectation" class="input" rows="4" required /></label><label class="field"><span>页面路径（每行一个）</span><textarea v-model="paths" class="input" rows="3" /></label><label v-if="edit.kind==='template'" class="field"><span>动态模板的样本与边界路径（每行一个）</span><textarea v-model="samples" class="input" rows="3" /></label><Disclosure v-if="edit.kind==='data'" label="全部预期记录标识"><textarea v-model="keys" class="input" rows="5" placeholder="每行一个产品 / 文章等记录标识" /></Disclosure><div class="manifest-flags"><label class="check-label"><input v-model="edit.required" type="checkbox" />必须完成</label><label v-for="v in ([['desktop','PC'],['mobile','移动端'],['business','业务 / 实现']] as const)" :key="v[0]" class="check-label"><input v-model="edit.viewports" type="checkbox" :value="v[0]" />{{v[1]}}</label></div><p v-if="visual" class="text-muted small-text">页面需提供相应视口的真实截图，动态内容还需全量数据与路由核验。</p><label class="field"><span>调整原因</span><input v-model="reason" class="input" required /></label><div class="manifest-actions"><button class="button secondary" type="button" @click="edit=undefined">取消</button><button class="button primary" :disabled="busy"><Save :size="15" />保存版本</button></div></form>
  <div v-else class="table-scroll"><table class="task-table"><thead><tr><th>交付项</th><th>类型</th><th>范围</th><th /></tr></thead><tbody><tr v-for="item in data.items" :key="item.id"><td><Disclosure :label="item.title"><p class="task-prose">{{item.expectation}}</p><p class="text-muted">来源：{{item.source}}</p><p class="task-prose">{{item.paths.join('、')}}</p></Disclosure></td><td>{{requirementKindNames[item.kind]}}</td><td>{{item.required?'必交付':'可选'}}{{item.expectedCount!==null?' · '+item.expectedCount+' 项':''}}</td><td><button v-if="data.editable" class="icon-button" aria-label="编辑条目" @click="start(item)"><Pencil :size="15" /></button></td></tr></tbody></table></div><TablePagination v-if="!edit&&data.total" :page="data.page" :pages="data.pages" :total="data.total" :busy="loading" @change="page=$event" /></section><p v-if="loadError" class="alert error">{{loadError}}<button class="text-action" @click="load">重试</button></p></template>
<style scoped>.manifest-editor{display:grid;gap:16px;padding:18px 0}.manifest-flags,.manifest-actions{display:flex;align-items:center;gap:20px;flex-wrap:wrap}.manifest-actions{justify-content:flex-end}</style>
